"""Four original cost/safety directions using existing genuine measured RUL.

Source/model reuse is outcome-known to the researcher. No refits or new final
scores occur in preparation. Unsupported risk, prices and actions stay unknown.
"""
import argparse
from datetime import datetime,timezone
import hashlib
import json
from pathlib import Path
import shutil
import urllib.request

from acquire_forge_pdmb_sources244 import save,sha256
from prepare_forge_coding_baseline import PYTHON,RUNTIME
from run_validation_transfer import freeze,metadata_gate,execute_wave,state

PROJECT=Path(__file__).resolve().parents[1]


def read(p):return json.loads(Path(p).read_text())


COMMON="""
Complete the original PHMForge request using the supplied measured laboratory RUL observations and genuinely fitted models. This is an explicitly partial numerical research adaptation: actual RUL prediction and any fully specified arithmetic can be checked independently. Laboratory annotations do not establish calibrated physical failure probabilities, legal compliance, downtime or causal maintenance savings. Unsupported quantities must remain unknown rather than being generated by a placeholder tool.

Final observations, labels and scores are absent during coding. Fit preprocessing and predictors on permitted learning data only. Preserve whole-bearing groups for validation and causal time boundaries. Use the actual saved program on target-free development observations; separate fitting, CV and development evidence. Do not invent final metrics. A lower MAE is better without a positive minimum bound.

Save solution.py, validation.json and report.md, and every fitted artifact required for independent inference. Invocation: python3 solution.py --input OBSERVATION_NPZ --output PREDICTION_JSON. Output predictions contains exactly one row per provided sample_id, with original unit_id, scenario_id and finite nonnegative predicted_rul in the specified unit. Include decision_evidence explaining the supplied facts, unavailable quantities and conditional recommendations. No test_predictions.json can be produced before the evaluator releases the final input.

/data,/reference,/tools are read-only. Python3.12,NumPy,SciPy,scikit-learn,PyTorch and actual MCP tools are available. Inspect their real implementations. You may keep a useful supplied predictor or write/train a new one; no change is required. All temporary files/caches belong under /app/.runtime, never /tmp. No Internet,packages,other tasks,hidden labels or other model APIs. Budget:3600seconds,180 model requests,18000000 completed input tokens,32768 output tokens/request,262144 total output tokens,two numerical threads.
"""


def build(root):
    assert read(root/'SOURCE_STATUS315.json')['status']=='hash_bound_RUL_sources_ready_for_fresh_scoped_cohort_preparation'
    assert not (root/'CAMPAIGN_CONFIG.json').exists()
    prior=Path(read(PROJECT/'results/safety314/current_run.json')['run'])/'c'
    online=read(prior/'audit/CLI_ONLINE_CHECK.json')
    with urllib.request.urlopen(urllib.request.Request('https://api.github.com/repos/openai/codex/releases/latest',headers={'User-Agent':'PHM-research'}),timeout=40) as response:
        raw=response.read();http=response.status
    release=json.loads(raw);assert release['tag_name']=='rust-v'+online['latest_stable_version']
    assert sha256(Path(online['CLI_path']))==online['CLI_sha256']
    online.update(checked_utc=datetime.now(timezone.utc).isoformat(),http_status=http,latest_response_sha256=hashlib.sha256(raw).hexdigest())
    save(root/'audit/CLI_ONLINE_CHECK.json',online);(root/'audit/CLI_LATEST_RELEASE.json').write_bytes(raw)
    original=read(Path('/data/yyf-zyq/PHM_20261010/20261023T105942Z_coverage306/source/original/source/official/ReActXen/src/reactxen/demo/intent_implementation_demo/scenarios/phm_scenarios.json'))['pdm_scenarios']
    originals={v['task_id']:v for v in original}
    cases=[dict(cohort='f1',dataset='FEMTO',task_id='pdm_cost_benefit_003'),
           dict(cohort='f2',dataset='FEMTO',task_id='pdm_safety_008'),
           dict(cohort='x1',dataset='XJTU',task_id='pdm_cost_benefit_004'),
           dict(cohort='x2',dataset='XJTU',task_id='pdm_safety_009')]
    budget=dict(subject_timeout_seconds=3600,max_model_requests_per_subject=180,max_total_input_tokens_per_subject=18000000,
        max_output_tokens_per_request=32768,max_total_output_tokens_per_subject=262144,mcp_tool_timeout_seconds=180,
        max_concurrency=8,local_max_concurrency=1,artifact_budget_bytes=4*1024**3)
    config=dict(iteration='A315',result_directory='results/rulfollow315',cases=cases,planned_sessions=4,session_budget=budget,
        purpose='Four original measured-RUL cost/safety directions: actual prediction and specified arithmetic, explicit missing physical decision contracts.',
        authorization='用户：把PHMforge能真实实验的全做了，并以此实验数据进行分析并验证问题。',
        test_inputs_visible=False,prior_source_scores_known_to_researcher=True,new_independent_sources=0,
        no_automatic_final_scoring=True,no_automatic_review_or_retry=True,physical_safety_or_maintenance_benefit_certified=False)
    save(root/'CAMPAIGN_CONFIG.json',config)
    femto=root/'source/femto/rul/source_data';xjtu=root/'source/xjtu'
    common=root/'common';tools=common/'public_tools';tools.mkdir(parents=True)
    for f in ['verified_phmforge.py','verified_benchmark_worker.py','verified_benchmark_scoring.py','real_fault_model.py',
              'real_rul_model.py','real_bearing_rul_model.py','real_xjtu_rul_model.py','isolated_model_gateway.py']:
        shutil.copy2(PROJECT/'scripts'/f,tools/f)
    for dataset,source in [('FEMTO',femto/'public'),('XJTU',xjtu/'public_data')]:
        public=common/dataset/'public';data=public/'datasets'/dataset
        shutil.copytree(source/'datasets'/dataset,data,ignore=shutil.ignore_patterns('test.npz','changed_input.npz'))
        info=read(data/'dataset.json')
        if dataset=='FEMTO':
            learning={int(v['unit_id']) for v in info['units'] if v['split']=='learning'}
            info['units']=[v for v in info['units'] if int(v['unit_id']) in learning]
            for p in (data/'trajectories').iterdir():
                if int(p.stem.removeprefix('unit')) not in learning:p.unlink()
            info['validation_scope']='Final supplied reference refits all six learning bearings; its metrics on these learning-bearing queries are not independent holdout metrics. Preserve whole-bearing CV for selection.'
        save(data/'dataset.json',info)
        save(public/'dataset_registry.json',{dataset:dict(task='rul',format=dataset.lower()+'_npz',path='datasets/'+dataset,architectures=['mlp'],available_splits=['train','val'],test_inputs_visible=False)})
        shutil.copy2(RUNTIME/'public/tool_catalog.json',public/'tool_catalog.json')
        reference=common/dataset/'reference'
        if dataset=='FEMTO':
            reference.mkdir();f=femto/'qualification_output/FEMTO_mlp_75962e259383'
            for name in ['model.pt','training_audit.json']:shutil.copy2(f/name,reference/name)
        else:shutil.copytree(xjtu/'references',reference)
    for case in cases:
        run=root/case['cohort'];dataset=case['dataset'];ident='rulfollow315_'+case['cohort']
        for d in ['audit','logs','code','runtime/tmp','runtime/mpl','plans','workspaces']:(run/d).mkdir(parents=True)
        ws=run/'workspaces'/ident;ws.mkdir()
        for d in ['.runtime/tmp','.runtime/mpl','.runtime/xdg','artifacts']:(ws/d).mkdir(parents=True)
        backend='real_bearing_rul_model' if dataset=='FEMTO' else 'real_xjtu_rul_model'
        checkpoint='/reference/model.pt' if dataset=='FEMTO' else '/reference/candidates/rf200.joblib'
        (ws/'solution.py').write_text("import argparse,sys\nfrom pathlib import Path\nsys.path.insert(0,'/tools')\nfrom "+backend+" import infer\np=argparse.ArgumentParser();p.add_argument('--input',type=Path,required=True);p.add_argument('--output',type=Path,required=True)\na=p.parse_args();infer(Path('"+checkpoint+"'),a.input,a.output)\n")
        (ws/'AGENTS.md').write_text('Use genuine measured data and saved fits; respect whole-bearing and causal-time boundaries. No final observations or scores. Temporary files only under /app/.runtime.\n')
        question=originals[case['task_id']]['input_question'];(ws/'TASK.txt').write_text(question+'\n')
        if dataset=='FEMTO':
            detail="""
FEMTO target unit is SECONDS. Six complete PRONOSTIA learning bearings span scenarios1:1800rpm/4000N,2:1650rpm/4200N,3:1500rpm/5000N. train.npz contains learning trajectories; val.npz provides historical30/60/90percent queries from three learning bearings. The supplied three-scenario MLP performed whole-bearing selection followed by refitting all six learning bearings; do not label its in-fitting development scores independent. training_config.json and permitted learning-only trajectories are available. Final observed prefixes for eleven bearings are sealed. Predict each endpoint using current/past observations, never an assumed fraction of life. Use the nominal10second acquisition clock documented by the source; original logger anomalies and annotation ambiguity are retained externally.
For cost003 only, the question specifies base preventive cost4000 and scenario multipliers1.0,1.2,1.5; compute any per-scenario preventive arithmetic from distinct bearings, not feature rows. No failure-price model, action effects, downtime, decision horizon or optimal threshold is supplied. Mark resulting failure costs, optimal strategy and savings unknown unless explicitly conditional. For safety008, no calibrated risk or regulatory pass criterion is supplied.
"""
        else:
            detail="""
XJTU target unit is nominal MINUTES to the original terminal acquisition. train.npz has nine complete measured fitting bearings; val.npz has one causal prefix for each of three development bearings with its history_offsets. Final evaluation invokes ONE query and its own causal history per fresh process, on fifteen prespecified queries from three other bearings. No other final prefix, labels or endpoint lengths are accessible. Fifteen queries are not fifteen independent bearings. The real six-model bank supplies train-only fitted artifacts, whole-bearing CV and development metrics; the initial program uses the previously fixed rf200 model. New fitting/selection may use training/development evidence only, not train-plus-development refitting.
Terminal teardown damage locations are not current per-minute fault observations. For cost004, the base maintenance price3500 and five multipliers are given but their mapping to current faults, failure prices, downtime and action effects are not defined. Do not fabricate a fault-at-prefix label or claim an optimal schedule. For safety009, physical risk calibration and shutdown criteria remain unknown. Save per-query RUL and explain these evidence boundaries.
"""
        prompt=run/'plans'/(ident+'.txt');prompt.write_text(question+'\n'+COMMON+detail)
        job=dict(id=ident,family='forge_measured_rul',task_id=case['task_id'],condition='coding_baseline',repeat=1,workspace=str(ws),prompt_file=str(prompt),answer_mode='text')
        plan=run/'plans'/(ident+'.json');save(plan,dict(jobs=[job]))
        mounts=run/'plans'/(ident+'_mounts.json');save(mounts,dict(mounts=[
            dict(source=str(PYTHON),destination='/opt/python312'),dict(source=str(RUNTIME/'deps'),destination='/opt/phm_python/extra'),
            dict(source=str(tools),destination='/tools'),dict(source=str(common/dataset/'public'),destination='/data'),dict(source=str(common/dataset/'reference'),destination='/reference')]))
        socket=run/'ipc/s0.sock'
        save(run/'PLAN187.json',dict(jobs=[dict(job,workspace=str(ws.relative_to(run)),plan=str(plan),mounts=str(mounts),model_gateway_socket=str(socket),dataset=dataset,data_format=dataset.lower()+'_npz',test_inputs_visible_during_development=False)]))
        protocol=dict(budget,model='deepseek-flash',cli=online['CLI_path'],cli_sha256=online['CLI_sha256'],max_new_model_sessions=1,max_new_primary_rolling24h=400,
            training_gate='TASK_QUALIFICATION251.json',environment_gate='AGENT_ISOLATION_GATE251.json',authorization_record='audit/AUTHORIZATION251.json',
            controller_status_name='CONTROLLER_STATUS251.json',external_model_gateway=True,test_inputs_visible=False,original_benchmark_score_claimed=False,
            additional_gates=['PUBLIC_METADATA_GATE267.json','NATIVE_CLI_MCP_QUALIFICATION.json','OUTPUT_BUDGET_QUALIFICATION.json'])
        save(run/'PROTOCOL187.json',protocol)
        save(run/'MODEL_GATEWAY_CONFIG.json',dict(routes=[dict(job=ident,socket=str(socket))],base_url='https://api.deepseek.com/',model='deepseek-flash',
            max_requests=180,max_input_tokens=18000000,max_output_tokens=262144,max_output_per_request=32768))
        for name in ['cli_config187.toml','model_catalog187.json']:shutil.copy2(prior/name,run/name)
        shutil.copy2(root/'audit/CLI_ONLINE_CHECK.json',run/'audit/CLI_ONLINE_CHECK.json')
        save(run/'TASK_QUALIFICATION251.json',dict(passed=True,research_adaptation=True,actual_measured_RUL=True,genuine_reference_fit_reused=True,
            original_task_id=case['task_id'],full_physical_decision_contract_qualified=False,source_binding='audit/SOURCE_BINDINGS315.json'))
        save(run/'audit/AUTHORIZATION251.json',dict(user_reply=config['authorization'],scope=config['purpose']))
        save(run/'OWNERSHIP.json',dict(owner='root',writers_stopped=True,status='prepared_waiting_isolation'))
        metadata_gate(run);freeze(run)
        p=run/'INITIAL_FREEZE187_FIFO_FILES.json';v=read(p);known={r['path'] for r in v['files']}
        for tree in [tools,common/dataset/'reference']:
            for path in tree.rglob('*'):
                if path.is_file() and str(path) not in known:v['files'].append(dict(path=str(path),sha256=sha256(path)))
        save(p,v)
    shutil.copy2(__file__,root/'code'/Path(__file__).name)
    state(root,status='four_original_RUL_followups_prepared',new_model_sessions=0,final_scores_opened=False,physical_risk_or_optimal_maintenance_validated=False)


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--phase',choices=['build','run'],required=True)
    a=p.parse_args();root=a.run.resolve()
    if a.phase=='build':build(root)
    else:execute_wave(root,'four_original_RUL_followups',[root/c for c in ['f1','f2','x1','x2']])
